package dev.unvoid.originceiler

import java.io.ByteArrayInputStream
import java.io.DataInputStream
import java.util.Base64
import java.util.zip.GZIPInputStream

/** Generated from the full BlueLM 6.4.9.21 resource catalogue of the reference device. */
internal object BlueLmRussianTranslations {
    private data class Catalog(
        val resources: Map<String, String>,
        val text: Map<String, String>
    )

    private val catalog: Catalog by lazy(LazyThreadSafetyMode.PUBLICATION, ::decode)

    fun resource(packageName: String, resourceName: String): String? =
        catalog.resources["$packageName\u0000$resourceName"]

    fun text(source: String): String? = catalog.text[source]

    private fun decode(): Catalog {
        val bytes = Base64.getDecoder().decode(PAYLOAD)
        return decodeCatalog(bytes)
    }

    private fun decodeCatalog(bytes: ByteArray): Catalog =
        DataInputStream(GZIPInputStream(ByteArrayInputStream(bytes))).use { input ->
            val resourceCount = input.readInt()
            val resources = HashMap<String, String>(resourceCount * 2)
            repeat(resourceCount) {
                val packageName = input.readUtf8()
                val name = input.readUtf8()
                resources["$packageName\u0000$name"] = input.readUtf8()
            }
            val textCount = input.readInt()
            val text = HashMap<String, String>(textCount * 2)
            repeat(textCount) { text[input.readUtf8()] = input.readUtf8() }
            Catalog(resources, text)
        }

    private fun DataInputStream.readUtf8(): String {
        val size = readInt()
        val bytes = ByteArray(size)
        readFully(bytes)
        return bytes.toString(Charsets.UTF_8)
    }


    private val PAYLOAD = listOf(
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        "",
        ""
    ).joinToString("")
}
